cd ~/costopt && cat > cost.js <<'EOF'
const {execFileSync}=require('child_process');
const OD_CPU=0.0335, OD_GIB=0.0045, SPOT=0.30, HOURS=730;
const env={...process.env, KUBECONFIG:process.env.HOME+'/kubeconfig'};
const k=a=>JSON.parse(execFileSync('kubectl',a,{env,maxBuffer:1e8}));
const cpu=s=>String(s).endsWith('m')?parseFloat(s)/1000:parseFloat(s);
const mem=s=>{s=String(s);const u={Ki:1/1048576,Mi:1/1024,Gi:1};for(const x in u)if(s.endsWith(x))return parseFloat(s)*u[x];return parseFloat(s)/2**30;};
const tag=process.argv[2]||'snap';
const nodes=k(['get','nodes','-o','json']);
const spot=new Set(nodes.items.filter(n=>(n.metadata.labels||{})['cloud.google.com/gke-spot']==='true').map(n=>n.metadata.name));
const pods=k(['-n','apps','get','pods','-o','json']);
const place={};
for(const p of pods.items){if(p.status.phase!=='Running'&&p.status.phase!=='Pending')continue;const a=p.metadata.labels.app;(place[a]=place[a]||[]).push(spot.has(p.spec.nodeName));}
const deps=k(['-n','apps','get','deploy','-o','json']).items.sort((a,b)=>a.metadata.name<b.metadata.name?-1:1);
let tot=0;const rows=[];
for(const d of deps){
  const nm=d.metadata.name,r=d.spec.replicas;
  const c=d.spec.template.spec.containers.reduce((s,x)=>s+cpu(x.resources.requests.cpu),0);
  const m=d.spec.template.spec.containers.reduce((s,x)=>s+mem(x.resources.requests.memory),0);
  const pl=place[nm]||[];const ns=pl.filter(Boolean).length, nod=pl.length-ns;
  const per=(c*OD_CPU+m*OD_GIB)*HOURS;
  const cost=nod*per+ns*per*SPOT; tot+=cost;
  rows.push([nm,r,c,m,nod,ns,cost]);
}
console.log(`--- ${tag} ---`);
console.log('workload'.padEnd(16)+'rep'.padStart(4)+'cpu/rep'.padStart(9)+'gib/rep'.padStart(9)+'onDem'.padStart(7)+'spot'.padStart(6)+'$/mo'.padStart(10));
for(const [nm,r,c,m,nod,ns,cost] of rows)console.log(nm.padEnd(16)+String(r).padStart(4)+c.toFixed(3).padStart(9)+m.toFixed(3).padStart(9)+String(nod).padStart(7)+String(ns).padStart(6)+cost.toFixed(2).padStart(10));
console.log('TOTAL'.padEnd(16)+''.padStart(35)+tot.toFixed(2).padStart(10));
EOF
node cost.js BASELINE | tee baseline.txt
